<!-- @generated by qw-codegen (crud) -->
<template>
  <view class="qw-detail qw-stack">
    <template v-if="row">
      <wd-cell-group custom-class="qw-group" border>
        <wd-cell :title="t('field.demo.book.isbn')" :value="row.isbn" />
        <wd-cell :title="t('field.demo.book.title')" :value="row.title" />
        <wd-cell :title="t('field.demo.book.author')" :value="row.author" />
        <wd-cell :title="t('field.demo.book.coverUrl')">
          <wd-img
            v-if="row.coverUrl"
            :src="assetUrl(row.coverUrl)"
            :width="64"
            :height="64"
            mode="aspectFill"
          />
        </wd-cell>
        <wd-cell :title="t('field.demo.book.publishedOn')" :value="row.publishedOn" />
        <wd-cell :title="t('field.demo.book.price')" :value="row.price.toFixed(2)" />
        <wd-cell :title="t('field.demo.book.genre')" :value="dictText('demo.genre', row.genre)" />
        <!-- The id, as the web's detail outside the caller's tree; names when mobile has a lookup -->
        <wd-cell :title="t('field.demo.book.deptId')" :value="row.deptId" />
        <wd-cell
          :title="t('field.demo.book.enabled')"
          :value="dictText('core.enabled', row.enabled)"
        />
        <wd-cell
          :title="t('field.common.createdAt')"
          :value="row.createdAt ? formatTime(row.createdAt) : ''"
        />
      </wd-cell-group>
      <QwPerm :perm="bookPerms.modify">
        <wd-button custom-class="qw-btn qw-btn--primary" type="primary" block @click="edit">
          {{ t('crud.action.edit') }}
        </wd-button>
      </QwPerm>
      <QwPerm :perm="bookPerms.remove">
        <wd-button
          custom-class="qw-btn"
          type="danger"
          variant="plain"
          block
          :loading="removing"
          :disabled="removing"
          @click="remove"
        >
          {{ t('crud.action.delete') }}
        </wd-button>
      </QwPerm>
    </template>
    <QwEmpty v-else-if="error" :title="error" />
  </view>
</template>

<script setup lang="ts">
import { ref, shallowRef } from 'vue'
import { onLoad, onShow } from '@dcloudio/uni-app'
import { bookPerms, type BookVo } from '@qiwu/shared'
import { bookApi } from '@/api/demo/book'
import QwEmpty from '@/core/components/QwEmpty.vue'
import QwPerm from '@/core/components/QwPerm.vue'
import { useDicts } from '@/core/crud'
import { formatTime } from '@/core/format'
import { t } from '@/core/i18n'
import { ApiError, assetUrl, errorText } from '@/core/request'

/**
 * One book (mobile, generated): `?id=`; GET /:id answers only a row in the caller's scope (else
 * 404, shown with its message). Showing again (back from its form) reloads it.
 */
const id = ref(0)
const row = shallowRef<BookVo>()
const error = ref('')
const { dictText } = useDicts(['demo.genre', 'core.enabled'])

async function load() {
  try {
    row.value = await bookApi.get(id.value)
  } catch (e) {
    error.value = errorText(e)
  }
}

onLoad((query) => {
  id.value = Number(query?.id) || 0
  uni.setNavigationBarTitle({ title: t('crud.title.detail', { name: t('demo.book.entity') }) })
})
// the first show loads too
onShow(() => void load())

const edit = () => uni.navigateTo({ url: `/pages-biz/demo/book/form?id=${id.value}` })

const removing = ref(false)
function remove() {
  uni.showModal({
    title: t('crud.confirm.title'),
    content: t('crud.confirm.delete'),
    confirmText: t('crud.action.delete'),
    cancelText: t('common.action.cancel'),
    success: async ({ confirm }) => {
      if (!confirm || removing.value) return
      removing.value = true
      try {
        await bookApi.remove(id.value)
        uni.showToast({ title: t('crud.msg.deleted'), icon: 'none' })
        uni.navigateBack()
      } catch (e) {
        // the request layer toasts a 409 (still in use: a reference, a tree node's children); a row gone
        // meanwhile (404) here
        if (e instanceof ApiError && e.status === 404)
          uni.showToast({ title: e.message, icon: 'none' })
      } finally {
        removing.value = false
      }
    },
  })
}
</script>
